from __future__ import annotations

from pathlib import Path
from typing import Any

from sentry.utils import json

# Generated by `pnpm gen:embed-widgets` from the frontend Seer embed schema
# definitions. Do not edit embed_widgets.generated.json by hand.
_WIDGETS: list[dict[str, Any]] = json.loads(
    (Path(__file__).parent / "embed_widgets.generated.json").read_text()
)


def get_embed_widgets(organization: Any = None, actor: Any = None) -> list[dict[str, Any]]:
    """Return embed widget definitions, filtered by per-widget feature flags.

    Each widget entry may include a ``featureFlag`` key (set in ``seerTags.ts``).
    When present the widget is only included if the org has that flag enabled.
    Widgets without ``featureFlag`` are always included.
    """
    has_flags = any("featureFlag" in w for w in _WIDGETS)
    if not has_flags:
        return _WIDGETS

    from sentry import features

    def _has_widget_flag(widget: dict[str, Any]) -> bool:
        if "featureFlag" not in widget:
            return True
        if organization is None:
            return False
        flag = widget["featureFlag"]
        # The frontend schema stores the bare flag name (e.g. "seer_agent_autofix");
        # organization features are registered under the "organizations:" scope.
        if ":" not in flag:
            flag = f"organizations:{flag}"
        return features.has(flag, organization, actor=actor)

    return [w for w in _WIDGETS if _has_widget_flag(w)]
